import{f as o,D as l,c as s,o as n,a5 as r,H as t}from"./chunks/framework.BsEAYNxL.js";const _=JSON.parse('{"title":"Worker：收益边界、OffscreenCanvas 与通信成本","description":"","frontmatter":{"title":"Worker：收益边界、OffscreenCanvas 与通信成本","date":"2026-01-20T00:00:00.000Z","categories":"study","tags":["browser-rendering","webworker","offscreen-canvas","performance","structured-clone"],"reading_stats":{"count":847,"minutes":3}},"headers":[],"relativePath":"browser-rendering/07-workers-offscreen-canvas-and-transfer-cost.md","filePath":"browser-rendering/07-workers-offscreen-canvas-and-transfer-cost.md","lastUpdated":1769026429000}'),i={name:"browser-rendering/07-workers-offscreen-canvas-and-transfer-cost.md"};function c(d,e,f,u,h,p){const a=l("InkMermaidBlock");return n(),s("div",null,[e[0]||(e[0]=r('<p>很多团队把“上 Worker”当成性能优化的银弹：主线程忙？挪出去。问题是，这个动作只对一类成本有效——<strong>纯计算</strong>。而浏览器渲染链路里最硬的一部分（style/layout/paint/composite/raster）并不会因为你挪走 JS 就自动变快。</p><p>这一章的目标是把 Worker 的收益边界讲清楚，并说明 OffscreenCanvas 这条“让 Worker 参与画画”的路径为什么既强大又容易踩坑。</p><h2 id="_1-worker-家族-别把它们当成一种东西" tabindex="-1">1. Worker 家族：别把它们当成一种东西 <a class="header-anchor" href="#_1-worker-家族-别把它们当成一种东西" aria-label="Permalink to &quot;1. Worker 家族：别把它们当成一种东西&quot;">​</a></h2><ul><li>Dedicated Worker：最常见，用于把计算挪出主线程</li><li>Shared Worker：多个页面共享（现实里少用，生态与限制更多）</li><li>Service Worker：偏网络/缓存/离线的中间层，不直接参与渲染</li></ul><p>这里讨论的“性能优化上 Worker”，默认指 Dedicated Worker。</p><h2 id="_2-结构化克隆-structured-clone-跨线程不是免费" tabindex="-1">2. 结构化克隆（structured clone）：跨线程不是免费 <a class="header-anchor" href="#_2-结构化克隆-structured-clone-跨线程不是免费" aria-label="Permalink to &quot;2. 结构化克隆（structured clone）：跨线程不是免费&quot;">​</a></h2><p>主线程与 Worker 通信的默认方式是 <code>postMessage</code>。它背后通常意味着：</p><ul><li>序列化/反序列化（structured clone）</li><li>任务排队（消息队列）</li><li>可能的拷贝（尤其大对象/深层对象）</li></ul><p>因此一个典型反直觉是：你把计算挪到 Worker，但每帧把一大坨结果传回来，反而更卡。</p><h3 id="_2-1-transferable-把-拷贝-变成-转移所有权" tabindex="-1">2.1 Transferable：把“拷贝”变成“转移所有权” <a class="header-anchor" href="#_2-1-transferable-把-拷贝-变成-转移所有权" aria-label="Permalink to &quot;2.1 Transferable：把“拷贝”变成“转移所有权”&quot;">​</a></h3><p>对 <code>ArrayBuffer</code> 这类对象，Transferable 可以把成本从“拷贝”变成“所有权转移”。它通常更快，但带来新的约束：</p><ul><li>主线程发送后 buffer 在主线程侧会变“不可用”</li><li>你需要设计好双缓冲/环形缓冲，避免频繁分配新 buffer</li></ul><h3 id="_2-2-sharedarraybuffer-共享带来速度-也带来治理成本" tabindex="-1">2.2 SharedArrayBuffer：共享带来速度，也带来治理成本 <a class="header-anchor" href="#_2-2-sharedarraybuffer-共享带来速度-也带来治理成本" aria-label="Permalink to &quot;2.2 SharedArrayBuffer：共享带来速度，也带来治理成本&quot;">​</a></h3><p>SharedArrayBuffer 允许共享内存，配合 Atomics 可以做低延迟协作。但它受安全策略约束（例如 cross-origin isolation），并且需要更严谨的并发设计。</p><h2 id="_3-worker-能解决什么-把-计算密集-与-渲染提交-拆开" tabindex="-1">3. Worker 能解决什么：把“计算密集”与“渲染提交”拆开 <a class="header-anchor" href="#_3-worker-能解决什么-把-计算密集-与-渲染提交-拆开" aria-label="Permalink to &quot;3. Worker 能解决什么：把“计算密集”与“渲染提交”拆开&quot;">​</a></h2><p>Worker 更擅长解决这些问题：</p><ul><li>大量纯计算：排版预处理、几何计算、数据解析、加密压缩、图像处理（取决于 API）</li><li>IO/解析：把大 JSON/二进制解析从主线程挪走（前提是传输与同步点可控）</li><li>任务切片：把长任务拆成更小的片段，降低主线程被长时间占用的概率</li></ul><p>Worker 不擅长解决这些问题：</p><ul><li>DOM/CSSOM 相关：layout/paint 的硬成本不会消失</li><li>频繁同步：每帧必须等 Worker 结果再继续（等待本身就是 jank 的根）</li></ul><h2 id="_4-offscreencanvas-让-worker-参与-画画-的少数路径" tabindex="-1">4. OffscreenCanvas：让 Worker 参与“画画”的少数路径 <a class="header-anchor" href="#_4-offscreencanvas-让-worker-参与-画画-的少数路径" aria-label="Permalink to &quot;4. OffscreenCanvas：让 Worker 参与“画画”的少数路径&quot;">​</a></h2><p>OffscreenCanvas 的核心价值是：把某些绘制工作（尤其 canvas）放到 Worker 线程执行，让主线程不再承担绘制相关的 JS 成本。</p><p>但它的上限通常被三件事决定：</p><ul><li>你传输的数据量与频率（大图像/大顶点数组每帧传输会很贵）</li><li>你是否引入了新的同步点（主线程等待 Worker 的帧结果）</li><li>GPU/栅格化是否已经是瓶颈（此时挪走 JS 收益会迅速变小）</li></ul>',23)),t(a,{codeBase64:""}),e[1]||(e[1]=r('<h2 id="_5-一个实用的判断题-你是在-挪走计算-还是在-引入通信税" tabindex="-1">5. 一个实用的判断题：你是在“挪走计算”，还是在“引入通信税” <a class="header-anchor" href="#_5-一个实用的判断题-你是在-挪走计算-还是在-引入通信税" aria-label="Permalink to &quot;5. 一个实用的判断题：你是在“挪走计算”，还是在“引入通信税”&quot;">​</a></h2><p>我更愿意把 Worker 优化当成一个简单的算账题：</p><ul><li>省下来的：主线程计算时间</li><li>新增的：消息传递/序列化/拷贝/同步等待</li></ul><p>当新增的通信税超过省下来的计算，Worker 就会从优化变成退化。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>MDN：Web Workers <a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API</a></li><li>MDN：OffscreenCanvas <a href="https://developer.mozilla.org/en-US/docs/Web/API/OffscreenCanvas" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/API/OffscreenCanvas</a></li></ul>',6))])}const W=o(i,[["render",c]]);export{_ as __pageData,W as default};
